// Algolia DocSearch v5 for the Chinese SDK documentation.
// Configuration is generated by docs/source/zh_CN/conf.py.
(function () {
  'use strict';

  var config = window.algoliaAgentChatConfig || {};
  var appId = config.appId;
  var apiKey = config.apiKey;
  var agentId = config.agentId;
  var indices = config.indices;

  if (!appId || !apiKey || !Array.isArray(indices) || indices.length === 0) {
    return;
  }

  function injectStylesheet(href) {
    if (document.querySelector('link[data-sifli-docsearch-href="' + href + '"]')) {
      return;
    }

    var link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = href;
    link.setAttribute('data-sifli-docsearch-href', href);
    document.head.appendChild(link);
  }

  function loadScript(src, isReady) {
    return new Promise(function (resolve, reject) {
      var existing = document.querySelector('script[data-sifli-docsearch-src="' + src + '"]');
      if (existing) {
        if (isReady()) {
          resolve();
        } else {
          existing.addEventListener('load', resolve, { once: true });
          existing.addEventListener('error', reject, { once: true });
        }
        return;
      }

      var script = document.createElement('script');
      script.src = src;
      script.async = true;
      script.setAttribute('data-sifli-docsearch-src', src);
      script.addEventListener('load', resolve, { once: true });
      script.addEventListener('error', reject, { once: true });
      document.head.appendChild(script);
    });
  }

  function isServerSearchTool(toolName) {
    return typeof toolName === 'string' &&
      (toolName === 'algolia_search_index' ||
        toolName.indexOf('algolia_search_index_') === 0);
  }

  function isResolvedToolOutput(eventType) {
    return eventType === 'tool-output-available' ||
      eventType === 'tool-output-error';
  }

  function isAgentCompletionRequest(input) {
    var url = typeof input === 'string' ? input : input && input.url;
    return typeof url === 'string' &&
      url.indexOf('/agent-studio/1/agents/' + agentId + '/completions') !== -1;
  }

  function installAgentStudioSearchToolCompatibilityShim() {
    // Agent Studio currently omits `providerExecuted` for its server-side
    // Algolia search events.  DocSearch v5 then mistakes that completed server
    // tool call for a client tool call and sends a second, invalid request after
    // the answer.  Mark only the documented server search tools as provider
    // executed on their resolved-output SSE events before they reach
    // DocSearch.  Incremental tool-input events do not allow this field.
    if (!agentId || window.__sifliAgentSearchToolShimInstalled ||
        typeof window.fetch !== 'function' ||
        typeof window.TransformStream !== 'function') {
      return;
    }

    var originalFetch = window.fetch.bind(window);
    window.__sifliAgentSearchToolShimInstalled = true;

    window.fetch = function (input, init) {
      return originalFetch(input, init).then(function (response) {
        if (!isAgentCompletionRequest(input) || !response.body) {
          return response;
        }

        var decoder = new TextDecoder();
        var encoder = new TextEncoder();
        var pending = '';
        var serverSearchCallIds = {};

        function rewriteLine(line) {
          var suffix = line.endsWith('\r') ? '\r' : '';
          var content = suffix ? line.slice(0, -1) : line;
          if (content.indexOf('data: ') !== 0) {
            return line;
          }

          try {
            var event = JSON.parse(content.slice(6));
            var toolCallId = event.toolCallId;
            if (isServerSearchTool(event.toolName)) {
              serverSearchCallIds[toolCallId] = true;
            }
            if (toolCallId && serverSearchCallIds[toolCallId] &&
                isResolvedToolOutput(event.type)) {
              event.providerExecuted = true;
              return 'data: ' + JSON.stringify(event) + suffix;
            }
          } catch (error) {
            // Non-JSON SSE events are not part of the AI SDK stream protocol.
          }
          return line;
        }

        var transformedBody = response.body.pipeThrough(new TransformStream({
          transform: function (chunk, controller) {
            pending += decoder.decode(chunk, { stream: true });
            var lines = pending.split('\n');
            pending = lines.pop();
            if (lines.length) {
              controller.enqueue(encoder.encode(lines.map(rewriteLine).join('\n') + '\n'));
            }
          },
          flush: function (controller) {
            pending += decoder.decode();
            if (pending) {
              controller.enqueue(encoder.encode(rewriteLine(pending)));
            }
          },
        }));

        return new Response(transformedBody, {
          status: response.status,
          statusText: response.statusText,
          headers: response.headers,
        });
      });
    };
  }

  function installTopSearchFocusGuard() {
    // DocSearch refreshes its result list while the user types.  On some
    // browsers that refresh can briefly leave focus on <body>, which makes the
    // next keystrokes appear to vanish.  Restore focus only for that specific
    // case; do not interfere with the intentional handoff to the Sidepanel.
    if (window.__sifliTopSearchFocusGuardInstalled) {
      return;
    }
    window.__sifliTopSearchFocusGuardInstalled = true;

    var isComposing = false;
    var focusCheckQueued = false;

    function isTopSearchInput(element) {
      return element && element.id === 'docsearch-input';
    }

    function canRestoreTopSearchFocus() {
      return document.body.classList.contains('DocSearch--active') &&
        document.querySelector('.DocSearch-Modal') &&
        !document.querySelector('.DocSearch-Sidepanel-Container.is-open') &&
        (document.activeElement === document.body ||
          document.activeElement === document.documentElement);
    }

    function queueFocusRestore(event) {
      if (!isTopSearchInput(event.target) || isComposing || focusCheckQueued) {
        return;
      }

      var selectionStart = event.target.selectionStart;
      var selectionEnd = event.target.selectionEnd;
      focusCheckQueued = true;
      window.requestAnimationFrame(function () {
        focusCheckQueued = false;
        if (!canRestoreTopSearchFocus()) {
          return;
        }

        // DocSearch may replace the input node during a render, so look it up
        // again instead of retaining the event target.
        var input = document.getElementById('docsearch-input');
        if (!input) {
          return;
        }
        input.focus({ preventScroll: true });
        if (typeof selectionStart === 'number' && typeof selectionEnd === 'number') {
          input.setSelectionRange(
            Math.min(selectionStart, input.value.length),
            Math.min(selectionEnd, input.value.length)
          );
        }
      });
    }

    document.addEventListener('compositionstart', function (event) {
      if (isTopSearchInput(event.target)) {
        isComposing = true;
      }
    }, true);
    document.addEventListener('compositionend', function (event) {
      if (isTopSearchInput(event.target)) {
        isComposing = false;
      }
    }, true);
    document.addEventListener('input', queueFocusRestore, true);
  }

  function ensureSidepanelRoot() {
    var root = document.getElementById('sifli-docsearch-sidepanel-root');
    if (root) {
      return root;
    }

    root = document.createElement('div');
    root.id = 'sifli-docsearch-sidepanel-root';
    root.style.position = 'relative';
    root.style.zIndex = '9999';
    document.body.appendChild(root);
    return root;
  }

  function initSearchModal() {
    if (!document.getElementById('docsearch')) {
      return;
    }

    loadScript(
      'https://cdn.jsdelivr.net/npm/@docsearch/js@5.0.3/dist/umd/index.js',
      function () { return typeof window.docsearch === 'function'; }
    )
      .then(function () {
        var searchConfig = {
          container: '#docsearch',
          appId: appId,
          apiKey: apiKey,
          indices: indices,
        };

        if (agentId) {
          // This enables the Ask AI item inside the normal DocSearch modal.
          // The v5 request can search every chip index for the current SDK
          // version; the current page's Agent decides the default chip.
          searchConfig.askAi = {
            agentId: agentId,
            indices: indices,
            searchParameters: config.searchParameters,
            suggestedQuestions: config.suggestedQuestions === true,
          };
        }

        window.docsearch(searchConfig);
      })
      .catch(function (error) {
        console.error('[DocSearch v5] search modal initialization failed:', error);
      });
  }

  function initSidepanel() {
    if (!agentId) {
      return;
    }

    injectStylesheet('https://cdn.jsdelivr.net/npm/@docsearch/css@5.0.3/dist/sidepanel.css');
    var root = ensureSidepanelRoot();
    loadScript(
      'https://cdn.jsdelivr.net/npm/@docsearch/sidepanel-js@5.0.3',
      function () { return typeof window.docsearchSidepanel === 'function'; }
    )
      .then(function () {
        window.docsearchSidepanel({
          container: root,
          appId: appId,
          apiKey: apiKey,
          agentId: agentId,
          indices: indices,
          searchParameters: config.searchParameters,
          button: {
            variant: config.variant || 'floating',
            translations: config.buttonTranslations,
          },
          panel: {
            variant: config.variant || 'floating',
            side: config.side || 'right',
            suggestedQuestions: config.suggestedQuestions === true,
            translations: config.translations,
          },
        });
      })
      .catch(function (error) {
        console.error('[DocSearch v5] sidepanel initialization failed:', error);
      });
  }

  function init() {
    // @docsearch/js@5's default UMD entry includes both keyword search and
    // its in-modal Ask AI experience. The CSS is shared with the Sidepanel.
    installAgentStudioSearchToolCompatibilityShim();
    installTopSearchFocusGuard();
    injectStylesheet('https://cdn.jsdelivr.net/npm/@docsearch/css@5.0.3/dist/style.css');
    initSearchModal();
    initSidepanel();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
